#include <stdio.h> #include <stdlib.h> #include <stdbool.h> // Structure for a node in the adjacency list struct Node { int data; struct Node* next; }; // Structure for the adjacency list struct List { struct Node* head; }; // Structure for a graph struct Graph { int vertices; struct List* array; }; // Create a new node struct Node* createNode(int data) { struct Node* newNode = (struct Node*)malloc(sizeof(struct Node)); newNode->data = data; newNode->next = NULL; return newNode; } // Create a graph with 'vertices' vertices struct Graph* createGraph(int vertices) { struct Graph* graph = (struct Graph*)malloc(sizeof(struct Graph)); graph->vertices = vertices; graph->array = (struct List*)malloc(vertices * sizeof(struct List)); for (int i = 0; i < vertices; i++) { graph->array[i].head = NULL; } return graph; } // Add an edge to the graph void addEdge(struct Graph* graph, int src, int dest) { struct Node* newNode = createNode(dest); newNode->next = graph->array[src].head; graph->array[src].head = newNode; newNode = createNode(src); newNode->next = graph->array[dest].head; graph->array[dest].head = newNode; } // Function to perform BFS void BFS(struct Graph* graph, int start) { bool* visited = (bool*)malloc(graph->vertices * sizeof(bool)); for (int i = 0; i < graph->vertices; i++) { visited[i] = false; } // Create a queue for BFS int* queue = (int*)malloc(graph->vertices * sizeof(int)); int front = 0, rear = 0; visited[start] = true; queue[rear++] = start; printf("Breadth-First Search starting from vertex %d:
", start); while (front < rear) { int current = queue[front++]; printf("%d ", current); struct Node* temp = graph->array[current].head; while (temp) { int neighbor = temp->data; if (!visited[neighbor]) { visited[neighbor] = true; queue[rear++] = neighbor; } temp = temp->next; } } free(visited); free(queue); printf("
"); } // Recursive function for Depth-First Search void DFSUtil(struct Graph* graph, int vertex, bool visited[]) { visited[vertex] = true; printf("%d ", vertex); struct Node* temp = graph->array[vertex].head; while (temp) { if (!visited[temp->data]) { DFSUtil(graph, temp->data, visited); } temp = temp->next; } } // Function to perform DFS void DFS(struct Graph* graph, int start) { bool* visited = (bool*)malloc(graph->vertices * sizeof(bool)); for (int i = 0; i < graph->vertices; i++) { visited[i] = false; } printf("Depth-First Search starting from vertex %d:
", start); DFSUtil(graph, start, visited); printf("
"); free(visited); } int main() { int vertices, edges, src, dest, start; printf("Enter the number of vertices: "); scanf("%d", &vertices); struct Graph* graph = createGraph(vertices); printf("Enter the number of edges: "); scanf("%d", &edges); for (int i = 0; i < edges; i++) { printf("Enter edge (source destination): "); scanf("%d %d", &src, &dest); addEdge(graph, src, dest); } printf("Enter the starting vertex for traversal: "); scanf("%d", &start); BFS(graph, start); DFS(graph, start); return 0; }
